fn batch_quality_metric<L>(
    stream_context: &StreamContext,
    source_0: &[ImageView<'_, u8, L>],
    source_1: &[ImageView<'_, u8, L>],
    channels: usize,
    metric: BatchQualityMetric<u8, L>,
) -> Result<ImageStatistic<f32>>
where
    L: ChannelLayout,
{
    stream_context.stream().ensure_not_capturing()?;
    let len = checked_len(
        Size::new(
            to_i32(source_0.len(), "source length")?,
            to_i32(channels, "metric channels")?,
        ),
        1,
    )?;
    let mut output = DeviceMemory::<f32>::create_uninit(stream_context.cuda_context(), len)?;
    stream_context.stream().ensure_not_capturing()?;
    for image in source_0 {
        stream_context.prepare_region(image)?;
    }
    for image in source_1 {
        stream_context.prepare_region(image)?;
    }
    stream_context.prepare_region(&output)?;
    stream_context.sync_scope(|| {
        // SAFETY: checked batch dispatch writes each channel result and the scope retains
        // image borrows, output storage, and native scratch until completion.
        unsafe {
            metric(
                stream_context,
                source_0,
                source_1,
                &mut DeviceOutputView::from_output(&mut output),
            )
        }
    })?;
    // SAFETY: successful completed dispatch initializes every batch result.
    Ok(ImageStatistic::from_values(unsafe { output.assume_init() }))
}
